import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.DQbZ8cc1.js";const b=JSON.parse('{"title":"生产环境部署","description":"","frontmatter":{},"headers":[],"relativePath":"zh/docs/installation/production.md","filePath":"zh/docs/installation/production.md"}'),o={name:"zh/docs/installation/production.md"};function d(s,a,r,c,n,h){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="生产环境部署" tabindex="-1">生产环境部署 <a class="header-anchor" href="#生产环境部署" aria-label="Permalink to “生产环境部署”">​</a></h1><p>完成安装方式选择后，再阅读这个页面。</p><h2 id="推荐生产配置" tabindex="-1">推荐生产配置 <a class="header-anchor" href="#推荐生产配置" aria-label="Permalink to “推荐生产配置”">​</a></h2><ul><li>使用 MySQL 8+。</li><li>在 BBS-GO 前面配置 Nginx、Caddy 或其他反向代理。</li><li>开启 HTTPS。</li><li>持久化并备份数据库、上传文件、配置文件和日志。</li><li>使用 systemd、supervisor、Docker 或平台进程管理能力保障服务持续运行。</li></ul><h2 id="端口" tabindex="-1">端口 <a class="header-anchor" href="#端口" aria-label="Permalink to “端口”">​</a></h2><table tabindex="0"><thead><tr><th>安装方式</th><th>默认对外端口</th></tr></thead><tbody><tr><td>发布包</td><td><code>8082</code></td></tr><tr><td>Docker</td><td><code>3000</code></td></tr></tbody></table><p>生产环境通常通过反向代理绑定域名，对外只暴露 HTTPS 端口。</p><h2 id="需要备份的数据" tabindex="-1">需要备份的数据 <a class="header-anchor" href="#需要备份的数据" aria-label="Permalink to “需要备份的数据”">​</a></h2><p>发布包部署：</p><ul><li>MySQL 数据库或 SQLite 数据库</li><li><code>bbs-go.yaml</code></li><li><code>res/uploads</code></li><li>需要保留的日志</li></ul><p>Docker 部署：</p><ul><li>使用内置 MySQL 时的 MySQL volume</li><li><code>/app/data</code></li><li><code>/app/logs</code></li><li><code>/app/res/uploads</code></li></ul><h2 id="反向代理" tabindex="-1">反向代理 <a class="header-anchor" href="#反向代理" aria-label="Permalink to “反向代理”">​</a></h2><p>反向代理转发到 BBS-GO 服务端口即可。</p><p>发布包默认目标：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8082</span></span></code></pre></div><p>Docker 默认目标：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:3000</span></span></code></pre></div><h2 id="升级检查清单" tabindex="-1">升级检查清单 <a class="header-anchor" href="#升级检查清单" aria-label="Permalink to “升级检查清单”">​</a></h2><ol><li>备份数据库和上传文件。</li><li>停止旧服务。</li><li>替换发布包或更新 Docker 镜像 tag。</li><li>启动新服务。</li><li>检查前台、管理后台、登录、上传和主要页面。</li></ol><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to “相关文档”">​</a></h2><ul><li><a href="./release.html">发布包安装</a></li><li><a href="./docker.html">Docker 部署</a></li></ul>',22)])])}const u=e(o,[["render",d]]);export{b as __pageData,u as default};
